// stateful — buffers everything, defeats laziness
sequenceOf(5, 3, 1, 4).sorted().take(2).toList()   // sorts all 4 first

// single-pass — iterate twice -> IllegalStateException
val gen = sequence {
    var i = 0
    while (true) { yield(i++) }
}
gen.first()      // 0
// gen.first()   // IllegalStateException: sequence can be consumed only once

// re-iterable — asSequence over a List
val s = listOf(1, 2, 3).asSequence()
s.toList(); s.toList()    // fine

// fusion win: early termination preserved
bigSeq.filter { }.map { }.first { }   // stops at first match

class Person(var name: String, val age: Int) {
    override fun equals(o: Any?) = o is Person && o.name == name && o.age == age
    override fun hashCode() = name.hashCode() * 31 + age
}

val p = Person("Ana", 30)
val set = hashSetOf(p)
set.contains(p)        // true
p.name = "Bella"       // hashCode changes...
set.contains(p)        // FALSE — element still in the set, bucket is stale

// data-class edges
val a = Base(1); val b = Sub(1)
a == b   // false — javaClass differs

class WithBody(val x: Int) {
    val cached: String = compute()   // excluded from equals/hashCode/copy
}

val tree = sortedSetOf<BigDecimal>()
tree.add(BigDecimal("1.0"))
tree.add(BigDecimal("1.00"))
tree.size   // 1 — compareTo says equal, equals disagrees

// overflow
val a = Int.MAX_VALUE; val b = -1
// a - b  ->  wraps negative, sorting wrong
compareValues(a, b)   // correct

// selector recomputation: precompute expensive keys
val byKey = list.map { it to expensive(it) }
    .sortedBy { it.second }
    .map { it.first }

// NaN sorts greater than everything
sortedSetOf(2.0, Double.NaN, 1.0)  // [1.0, 2.0, NaN]

